(* [comment removed for export] *)
Lemma rng_wr_sound : forall b k n,
  rng_wr_b b k n = true ->
  0 <= n /\ 0 <= bv_unsigned (edenot E b) + k /\ bv_unsigned (edenot E b) + k + n <= 2 ^ 64
