Definition ksubl_b (kn kn' : list kentry) : bool := forallb (ksub_b kn) kn'.

Lemma ksubl_sound : forall segs E M kn kn',
  know_ok segs E M kn -> ksubl_b kn kn' = true -> know_ok segs E M kn'.
Proof.
